{
  "resourceType": "Bundle",
  "type": "collection",
  "entry": [
    {
      "fullUrl": "https://example.org/fhir/Patient/patient-1",
      "resource": {
        "resourceType": "Patient",
        "id": "patient-1",
        "gender": "female"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-1",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-1",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Focal epilepsy with secondary generalization"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "note": [
          {
            "text": "Known epilepsy, well controlled on levetiracetam. No generalized tonic-clonic seizures since the admission approximately 18 months ago. Two early post-event auras, none for approximately 9–10 months. Currently stable with no red flags; ongoing antiepileptic treatment indicated to reduce recurrence risk, including further status epilepticus."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "History of convulsive status epilepticus"
        },
        "onsetString": "Approximately 18 months before this encounter",
        "note": [
          {
            "text": "Previous convulsive status epilepticus requiring ICU admission, supported by hospital discharge letter on file."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-3",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-3",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Shift work sleep disruption"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "note": [
          {
            "text": "Clinician assesses sleep disruption as a known seizure trigger and likely contributor to the initial event."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-4",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-4",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Mild cognitive fatigue and fogginess, especially on night shifts"
        },
        "clinicalStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-clinical",
              "code": "active"
            }
          ]
        },
        "note": [
          {
            "text": "Assessed as likely multifactorial from shift work/circadian disruption and Keppra; non-limiting, with no concerning adverse effects."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Generalized tonic-clonic seizure recurrence"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No generalized tonic-clonic seizures since the ICU admission approximately 18 months ago."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Reported seizure auras"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Two brief auras in the first 3 months after ICU admission, involving déjà vu, metallic taste and mild spacing out, lasting approximately 30 seconds. None during the last approximately 9–10 months."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Reported seizure-associated symptoms and recent precipitants"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies loss of consciousness, tongue biting, incontinence, recent head injury, illness or missed medication doses."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Medication adherence"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports taking medication daily using a phone alarm. Sometimes takes doses 1–2 hours late during night shifts, but does not miss doses."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Initial reported medication adverse effects"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Initial irritability and fatigue after starting Keppra have now settled."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Reported cognitive fogginess"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Possibly feels a little foggy, especially during night shifts; questions whether this is due to tablets or night shifts."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Reported adverse-effect screening"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies mood lability, suicidal ideation, rash, ataxia or visual symptoms."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Patient-reported possible seizure triggers"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient thinks the major seizure was related to many energy drinks and poor sleep during a run of night shifts. Also queries hospital Wi-Fi or monitors as triggers; clinician reassured this is unlikely and explained sleep deprivation and stress are more likely."
      }
    },
    {
